{
  "plan": "O programa usa checked_add em mint, portanto a hipotese de overflow aritmetico deve ser testada executando mint com amount = u64::MAX sobre um ledger cujo total_supply ja e 1. O baseline inicializa o ledger com initial_supply = 1 e depois chama mint com amount = 1, provando que o cenario esta montado corretamente. O ataque chama mint com amount = u64::MAX, que se vulneravel faria total_supply dar a volta; o efeito mede se total_supply resultante e menor que o valor anterior, indicando overflow em vez de falha.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let init_result = env.baseline("initialize ledger with supply 1", &init_ix, &init_accounts);

let ledger_after_init = after(&init_result, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init.clone()),
    (authority, wallet(1_000_000_000)),
];

let baseline_result = env.baseline("mint 1 token", &mint_ix, &mint_accounts);

let ledger_after_baseline = after(&baseline_result, &ledger_key).clone();
let supply_before_attack = read_u64(ledger_after_baseline.data(), 40);

let attack_ix = env.anchor_ix(
    "mint",
    &(u64::MAX,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = vec![
    (ledger_key, ledger_after_baseline.clone()),
    (authority, wallet(1_000_000_000)),
];

let attack_result = env.attack("mint u64::MAX causing overflow", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let supply_after_attack = read_u64(after(&attack_result, &ledger_key).data(), 40);
    env.effect(
        "total_supply wrapped around (overflow) instead of failing",
        supply_after_attack < supply_before_attack,
    );
}"
}

